import math
from collections.abc import Mapping


def _finite_number(value):
    return isinstance(value, (int, float)) and not isinstance(value, bool) and math.isfinite(value)


def build_histogram_grid(groups, samples, initial=None, *, bins=10):
    if not isinstance(groups, Mapping) or not isinstance(samples, Mapping):
        raise ValueError('groups and samples must be mappings')
    if initial is None:
        initial = {}
    if not isinstance(initial, Mapping):
        raise ValueError('initial must be a mapping')
    if not isinstance(bins, int) or isinstance(bins, bool) or bins < 1:
        raise ValueError('bins must be positive')
    names = []
    checked_groups = []
    for category, parameters in groups.items():
        if not isinstance(category, str) or isinstance(parameters, (str, bytes)):
            raise ValueError('invalid group')
        try:
            parameter_list = list(parameters)
        except TypeError:
            raise ValueError('invalid parameter sequence') from None
        if any(not isinstance(p, str) for p in parameter_list):
            raise ValueError('invalid parameter name')
        names.extend(parameter_list)
        checked_groups.append((category, parameter_list))
    if len(names) != len(set(names)) or set(samples.keys()) != set(names) or not set(initial.keys()).issubset(names):
        raise ValueError('parameter keys do not match')
    if any(not _finite_number(value) for value in initial.values()):
        raise ValueError('invalid initial value')
    checked_samples = {}
    for name in names:
        raw = samples[name]
        if isinstance(raw, (str, bytes)):
            raise ValueError('invalid samples')
        try:
            values = list(raw)
        except TypeError:
            raise ValueError('invalid samples') from None
        if not values or any(not _finite_number(v) for v in values):
            raise ValueError('invalid samples')
        checked_samples[name] = [float(v) for v in values]
    output = []
    for category, parameters in checked_groups:
        plots = []
        for name in parameters:
            values = checked_samples[name]
            low, high = min(values), max(values)
            counts = [0] * bins
            if low == high:
                edges = [low] * (bins + 1)
                counts[-1] = len(values)
            else:
                width = (high - low) / bins
                edges = [low + width * i for i in range(bins)] + [high]
                for value in values:
                    index = min(int((value - low) / width), bins - 1)
                    counts[index] += 1
            plots.append({'parameter': name, 'edges': list(edges), 'counts': list(counts), 'initial': float(initial[name]) if name in initial else None})
        output.append({'category': category, 'plots': plots})
    return output

